UPDATE app_state SET data=json_set(data,'$.feedbackMessages',json((
 SELECT json_group_array(json(CASE WHEN json_extract(value,'$.id')='47385206-76de-4d49-9974-9eeaaea65b66' THEN json_patch(value,json_object('status','done','adminComment','Versão 137 publicada: digitar @ abre sugestões por nome, com seleção por toque/clique ou teclado. Pessoas marcadas aparecem destacadas no comentário e na confirmação antes de enviar. O sino abre o comentário e expande sua seção automaticamente. Validado em tela móvel, temas claro/escuro e testes de permissões.','updatedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'completedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now'))) ELSE value END)) FROM json_each(app_state.data,'$.feedbackMessages')
))),revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1 AND EXISTS(SELECT 1 FROM json_each(data,'$.feedbackMessages') WHERE json_extract(value,'$.id')='47385206-76de-4d49-9974-9eeaaea65b66');
